size_t RegisterMPCImage(void)
{
    MagickInfo
        *magick_info;

    magick_info = (MagickInfo *) AcquireMagickMemory(sizeof(MagickInfo));
    if (magick_info == (MagickInfo *) NULL)
      return (size_t) 0;
    (void) memset(magick_info, 0, sizeof(MagickInfo));
    magick_info->signature = MagickSignature;
    magick_info->format = (const unsigned char *) "MPC";
    magick_info->description = (const char *) "Magick Persistent Cache";
    magick_info->module = (const char *) "MPC";
    magick_info->decoder = (DecodeImageHandler *) ReadMPCImage;
    magick_info->encoder = (EncodeImageHandler *) WriteMPCImage;
    magick_info->flags |= MagickSupportsCanvas;
    magick_info->flags |= MagickSupportsNativeEndian;
    magick_info->flags |= MagickSupportsSingleImage;
    magick_info->flags |= MagickSupportsMultipleImages;
    magick_info->flags |= MagickSupportsThreadedDecoding;
    magick_info->flags |= MagickSupportsThreadedEncoding;
    magick_info->page != (ImageGeometry *) NULL;
    magick_info->mime_type = (const char *) "application/x-magick";
    magick_info = GetMagickInfo("MPC", &magick_info);
    return (magick_info ? sizeof(*magick_info) : 0);
}

